// ServerInterface represents all server handlers.
type ServerInterface interface {
	// SendEmailCode 发送邮箱验证码
	// (POST /api/v1/auth/email-code)
	SendEmailCode(w http.ResponseWriter, r *http.Request)
	// GuestLogin 游客一键进入（simple 模式专属）
	// (POST /api/v1/auth/guest)
	GuestLogin(w http.ResponseWriter, r *http.Request)
	// Login 邮箱密码登录
	// (POST /api/v1/auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout 登出并吊销 refresh_token
	// (POST /api/v1/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// ResetPassword 邮箱验证码重置密码
	// (POST /api/v1/auth/password/reset)
	ResetPassword(w http.ResponseWriter, r *http.Request)
	// Refresh 刷新令牌（旋转 refresh_token）
	// (POST /api/v1/auth/refresh)
	Refresh(w http.ResponseWriter, r *http.Request)
	// Register 邮箱注册（simple 模式免验证码）
	// (POST /api/v1/auth/register)
	Register(w http.ResponseWriter, r *http.Request)
	// DeleteCategory 删除分类（owner/admin，默认仅删空分类）
	// (DELETE /api/v1/categories/{id})
	DeleteCategory(w http.ResponseWriter, r *http.Request, id IDPath, params DeleteCategoryParams)
	// PatchCategory 改分类名/排序（owner/admin）
	// (PATCH /api/v1/categories/{id})
	PatchCategory(w http.ResponseWriter, r *http.Request, id IDPath)
	// DeleteChannel 删除频道（owner/admin）
	// (DELETE /api/v1/channels/{id})
	DeleteChannel(w http.ResponseWriter, r *http.Request, id IDPath)
	// PatchChannel 改频道（owner/admin）
	// (PATCH /api/v1/channels/{id})
	PatchChannel(w http.ResponseWriter, r *http.Request, id IDPath)
	// ListMessages 消息分页（游标，倒序取页正序返回）
	// (GET /api/v1/channels/{id}/messages)
	ListMessages(w http.ResponseWriter, r *http.Request, id IDPath, params ListMessagesParams)
	// CreateMessage 发送文字消息（≤2000 字 + 频控 20/分 + nonce 幂等）
	// (POST /api/v1/channels/{id}/messages)
	CreateMessage(w http.ResponseWriter, r *http.Request, id IDPath)
	// GetConfig 服务端能力开关
	// (GET /api/v1/config)
	GetConfig(w http.ResponseWriter, r *http.Request)
	// ListFriends 好友与好友请求列表
	// (GET /api/v1/friends)
	ListFriends(w http.ResponseWriter, r *http.Request)
	// CreateFriendRequest 按 昵称#tag 发起好友请求
	// (POST /api/v1/friends/requests)
	CreateFriendRequest(w http.ResponseWriter, r *http.Request)
	// AcceptFriendRequest 接受好友请求（仅被请求方）
	// (POST /api/v1/friends/requests/{id}/accept)
	AcceptFriendRequest(w http.ResponseWriter, r *http.Request, id IDPath)
	// DeleteFriend 删除好友关系（双方任一方向）
	// (DELETE /api/v1/friends/{id})
	DeleteFriend(w http.ResponseWriter, r *http.Request, id IDPath)
	// PatchFriend 设置备注/分组（仅发起方）
	// (PATCH /api/v1/friends/{id})
	PatchFriend(w http.ResponseWriter, r *http.Request, id IDPath)
	// GetHealthz 健康检查（部署探活）
	// (GET /api/v1/healthz)
	GetHealthz(w http.ResponseWriter, r *http.Request)
	// PostRtcCredentials 签发 TURN 短期凭证
	// (POST /api/v1/rtc/credentials)
	PostRtcCredentials(w http.ResponseWriter, r *http.Request)
	// ListServers 我所在的服务器列表
	// (GET /api/v1/servers)
	ListServers(w http.ResponseWriter, r *http.Request)
	// CreateServer 创建服务器（创建者自动成为 owner）
	// (POST /api/v1/servers)
	CreateServer(w http.ResponseWriter, r *http.Request)
	// JoinServer 凭邀请码加入服务器
	// (POST /api/v1/servers/join)
	JoinServer(w http.ResponseWriter, r *http.Request)
	// DeleteServer 解散服务器（仅 owner）
	// (DELETE /api/v1/servers/{id})
	DeleteServer(w http.ResponseWriter, r *http.Request, id IDPath)
	// PatchServer 改服务器名称/图标（owner/admin）
	// (PATCH /api/v1/servers/{id})
	PatchServer(w http.ResponseWriter, r *http.Request, id IDPath)
	// CreateCategory 创建分类（owner/admin）
	// (POST /api/v1/servers/{id}/categories)
	CreateCategory(w http.ResponseWriter, r *http.Request, id IDPath)
	// ListChannels 服务器的分类与频道（成员可读）
	// (GET /api/v1/servers/{id}/channels)
	ListChannels(w http.ResponseWriter, r *http.Request, id IDPath, params ListChannelsParams)
	// CreateChannel 创建频道（owner/admin）
	// (POST /api/v1/servers/{id}/channels)
	CreateChannel(w http.ResponseWriter, r *http.Request, id IDPath)
	// CreateInvite 创建邀请码（owner/admin）
	// (POST /api/v1/servers/{id}/invites)
	CreateInvite(w http.ResponseWriter, r *http.Request, id IDPath)
	// ListServerMembers 服务器成员列表（成员可读）
	// (GET /api/v1/servers/{id}/members)
	ListServerMembers(w http.ResponseWriter, r *http.Request, id IDPath, params ListServerMembersParams)
	// GetSync 事件续传失败后的聚合快照
	// (GET /api/v1/sync)
	GetSync(w http.ResponseWriter, r *http.Request)
	// GetMe 当前用户（自响应，含 email）
	// (GET /api/v1/users/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// PatchMe 改昵称（无头像字段）
	// (PATCH /api/v1/users/me)
	PatchMe(w http.ResponseWriter, r *http.Request)
}

